INSERT INTO internal.pipeline_actions (operation, definition) VALUES
  ('convert_pipeline_to_standard', '{"operation":"convert_pipeline_to_standard","rpc":"convert_pipeline_to_standard","label":"Convert a Simple pipeline to Standard","description":"Turns a Simple pipeline (a recipe) into a Standard one (typed steps) and cannot be undone: the recipe goes and the steps it compiled to stay. The draft becomes Standard in place; with no draft the newest version is copied into a new Standard draft. The published version keeps running until the draft is published. Stewards, admins and owners. Returns the Standard draft version. Sends `pipeline.version.updated` or `pipeline.version.created`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false,"server":"workspace"},{"name":"p_definition_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('duplicate_pipeline_definition', '{"operation":"duplicate_pipeline_definition","rpc":"duplicate_pipeline_definition","label":"Duplicate a pipeline version as a new pipeline","description":"Makes a new pipeline from one version of another, in the mode that version was written in, starting as its first draft. Runs, starts and history stay with the original. `p_key` is letters, digits and `_`, unique in the workspace. Stewards, admins and owners. Returns the new pipeline. Sends `pipeline.created` and `pipeline.version.created`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false,"server":"workspace"},{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('create_inbox_item', '{"operation":"create_inbox_item","rpc":"create_inbox_item","label":"Leave an Inbox item for someone","description":"Puts an item in a person’s Inbox: a task to do or a snapshot to look at. Give the dataset or snapshot it is about, if it is about one, and a due time if there is one. It shows until they open it. Stewards and anyone who can edit in the workspace. Returns the item. Sends `pipeline.inbox_item.created`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false,"server":"workspace"},{"name":"p_user_id","type":"text","required":true,"nullable":false},{"name":"p_title","type":"text","required":true,"nullable":false},{"name":"p_body","type":"text","required":false,"nullable":false},{"name":"p_dataset_id","type":"uuid","required":false,"nullable":false},{"name":"p_dataset_version_id","type":"uuid","required":false,"nullable":false},{"name":"p_due_at","type":"timestamptz","required":false,"nullable":false}]}'::jsonb)
